  'help.type.other': 'Annat',
  'help.faq.cantLogin.q': 'Jag kan inte logga in på mitt konto',
  'help.faq.cantLogin.a': 'Se till att du använder rätt e-post och lösenord. Om du har glömt ditt lösenord, klicka på "Glömt lösenord?" på inloggningsskärmen. Om problemet kvarstår, skapa en supportbiljett.',
  'help.faq.notReceiving.q': 'Jag får inga e-postmeddelanden',
  'help.faq.notReceiving.a': 'Kolla först din skräppostmapp. Se till att ditt lagringsutrymme inte är fullt. Om problemet fortsätter, verifiera att avsändaren har rätt e-postadress och skapa en supportbiljett.',
  'help.faq.cantSend.q': 'Jag kan inte skicka e-post',
  'help.faq.cantSend.a': 'Verifiera din internetanslutning och att mottagarens e-postadress är korrekt. Kolla om du har några bilagor som är för stora (max 25MB). Försök igen om några minuter.',
  'help.faq.forgotPassword.q': 'Jag har glömt mitt lösenord',
  'help.faq.forgotPassword.a': 'På inloggningsskärmen, klicka på "Glömt lösenord?" och följ instruktionerna för att återställa ditt lösenord via din återställnings-e-postadress.',
  'help.faq.accountSecurity.q': 'Jag tror att mitt konto har blivit komprometterat',
  'help.faq.accountSecurity.a': 'Ändra omedelbart ditt lösenord. Kolla din skickade mapp efter meddelanden du inte har skickat. Aktivera tvåfaktorsautentisering i Inställningar > Säkerhet. Om det behövs, skapa en brådskande supportbiljett.',
  'help.faq.appAccess.q': 'Hur får jag tillgång till appen på mobilen?',
  'help.faq.appAccess.a': 'Du kan komma åt Chatyy via vilken mobil webbläsare som helst på chatyy.com.br, eller ladda ner vår app från din enhets appbutik.',

  // Privacy modal
  'privacy.title': 'Integritetspolicy',
  'privacy.subtitle': 'Hur vi skyddar och hanterar dina uppgifter',
  'privacy.lastUpdated': 'Senast uppdaterad: Mars 2026',
  'privacy.dataCollection.title': 'Datainsamling',
  'privacy.dataCollection.body': 'Vi samlar endast in den information som behövs för att tillhandahålla vår e-posttjänst: ditt namn, e-postadress och innehållet i meddelanden du skickar och tar emot. Vi säljer eller delar inte dina personuppgifter med tredje part för marknadsföringsändamål.',
  'privacy.dataUsage.title': 'Hur vi använder dina uppgifter',
  'privacy.dataUsage.body': 'Dina uppgifter används uteslutande för att driva och förbättra e-posttjänsten, inklusive att leverera meddelanden, filtrera skräppost, tillhandahålla AI-drivna funktioner (med ditt samtycke) och upprätthålla kontosäkerhet.',
  'privacy.dataSecurity.title': 'Datasäkerhet',
  'privacy.dataSecurity.body': 'Vi använder branschstandard kryptering (TLS/SSL) för all data i transit och i vila. Sessioner skyddas med krypterade tokens och CSRF-skydd. Vi granskar regelbundet våra säkerhetspraxis.',
  'privacy.cookies.title': 'Cookies & Lokal lagring',
  'privacy.cookies.body': 'Vi använder nödvändiga cookies och lokal lagring för att upprätthålla din session, komma ihåg dina inställningar (tema, språk) och ge en sömlös upplevelse. Vi använder inte spårningscookies från tredje part.',
  'privacy.thirdParties.title': 'Tredjepartstjänster',
  'privacy.thirdParties.body': 'Vi kan använda tredjepartstjänster för specifik funktionalitet som AI-funktioner (Anthropic Claude) och push-notiser. Dessa tjänster är bundna av sina egna integritetspolicys och bearbetar endast den minimiuppgift som krävs.',
  'privacy.rights.title': 'Dina rättigheter',
  'privacy.rights.body': 'Du har rätt att få tillgång till, korrigera, exportera eller radera dina personuppgifter när som helst. Du kan hantera dina uppgifter genom Inställningar eller genom att kontakta vårt supportteam.',
  'privacy.contact.title': 'Kontakta oss',
  'privacy.contact.body': 'För frågor relaterade till integritet eller databehov, kontakta oss på privacy@chatyy.com.br. Vi kommer att svara inom 30 dagar.',

  // Terms modal
  'terms.title': 'Användarvillkor',
  'terms.subtitle': 'Riktlinjer för att använda Chatyy',
  'terms.lastUpdated': 'Senast uppdaterad: Mars 2026',
  'terms.acceptance.title': 'Accepterande av villkor',
  'terms.acceptance.body': 'Genom att få tillgång till eller använda Chatyy, godkänner du att följa dessa användarvillkor. Om du inte håller med om någon del av dessa villkor, får du inte använda tjänsten.',
  'terms.services.title': 'Beskrivning av tjänster',
  'terms.services.body': 'Chatyy tillhandahåller e-postkommunikationstjänster inklusive att skicka, ta emot och hantera e-post, tillsammans med AI-drivna funktioner, kalenderintegration och videokonferensmöjligheter.',
  'terms.accounts.title': 'Användarkonton',
  'terms.accounts.body': 'Du är ansvarig för att upprätthålla säkerheten för dina kontouppgifter. Du får inte dela ditt lösenord eller tillåta obehörig åtkomst till ditt konto. Du måste vara minst 13 år gammal för att använda denna tjänst.',
  'terms.conduct.title': 'Acceptabel användning',
  'terms.conduct.body': 'Du går med på att inte använda tjänsten för att skicka skräppost, skadlig programvara, phishing eller något olagligt innehåll. Du får inte försöka få åtkomst till andra användares konton eller störa tjänstens infrastruktur.',
  'terms.content.title': 'Innehav av innehåll',
  'terms.content.body': 'Du behåller äganderätten till allt innehåll du skapar och skickar genom tjänsten. Vi gör inget anspråk på ägande över dina e-postmeddelanden eller bilagor. Vi kan bearbeta innehåll som nödvändigt för att tillhandahålla tjänsten.',
  'terms.limitation.title': 'Begränsning av ansvar',
  'terms.limitation.body': 'Chatyy tillhandahålls "som den är". Vi strävar efter 99,9% drifttid men garanterar inte oavbruten tjänst. Vi är inte ansvariga för några indirekta, tillfälliga eller följdskador som uppstår från din användning av tjänsten.',
  'terms.termination.title': 'Kontotermination',
  'terms.termination.body': 'Vi kan stänga av eller avsluta konton som bryter mot dessa villkor. Du kan radera ditt konto när som helst genom Inställningar. Vid avslutning kommer dina uppgifter att raderas inom 30 dagar.',
  'terms.changes.title': 'Ändringar av villkor',
  'terms.changes.body': 'Vi kan uppdatera dessa villkor från tid till annan. Vi kommer att meddela dig om betydande ändringar via e-post eller in-app-notifikation. Fortsatt användning av tjänsten efter ändringar utgör acceptans av de uppdaterade villkoren.',

